fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Collect the three indices into a small array
    let mut idxs = [i, j, k];
    // Sort the indices by the values they point to, in descending order
    idxs.sort_by(|&a, &b| valores[b].cmp(&valores[a]));
    // Return the top two indices
    (idxs[0], idxs[1])
}

